\label{def:integrable}
	A convex body $K\subset\mathbb R^n$ is \emph{algebraically integrable}
	if there is a nonzero polynomial
	$P(\eta,s,w)\in\mathbb R[\eta_1,\ldots,\eta_n,s,w]$ such that
	\begin{equation}\label{eq:cutoff-algebraic}
		P\bigl(\eta,s,\operatorname{vol}_n(K\cap\{x:\eta\cdot x\le s\})\bigr)=0
	\end{equation}
	whenever $\eta\in\mathbb R^n\setminus\{0\}$ and the hyperplane
	$\eta\cdot x=s$ intersects the interior of $K$.

\label{lem:real-analytic-sections}
For a convex body $K\subset\mathbb R^n$ with real analytic boundary and a fixed $\xi\inS^{n-1}$, the function $A_K(\xi,\cdot)$ is real analytic on $I_K(\xi)$. If $\partial K$ is only $C^\infty$ and $0\in\operatorname{int}K$, then $A_K(\xi,t)$ is $C^\infty$ as a function of $(\xi,t)$
in a neighborhood of $S^{n-1}\times\{0\}$.

\label{lem:compatible-pl}
A based meridian of $t_0$ follows the chosen path from $\tau$, traverses one small positively oriented circle around $t_0$, and returns along the path. We use $T$ for the monodromy automorphisms induced by this
loop on both $\mathsf A$ and $\mathsf H$. For one fixed sign $\epsilon\in\{1,-1\}$, the Picard--Lefschetz transformations are
\begin{align}
 Ta&=a+\epsilon\langle ja,v\rangle\delta,
 &&a\in\mathsf A,\label{eq:pl-open}\\
 Th&=h+\epsilon\langle h,v\rangle v,
 &&h\in\mathsf H.\label{eq:pl-compact}
\end{align}

\label{prop:semisimplicity}
Under the preceding hypotheses, assume that $d$ is odd. If $I_\delta$ is not identically zero and has finite branching on $U$, then
\begin{equation}\label{eq:null-compact}
 j\delta=0.
\end{equation}

\label{prop:boundary-entire}
Let $f:\mathcal M\to\mathbb C$ be a projective morphism from a smooth complex algebraic variety of dimension $d+1$. Let $\mathcal D\subset\mathcal M$ be a reduced divisor such that $f$ is smooth near $\mathcal D$ and $\mathcal D$ is a relative simple normal-crossing divisor over all of $\mathbb C$. Suppose $f$ is smooth over $U=\mathbb C\setminus\Sigma$, where $\Sigma$ is finite. Fix $\tau\in U$ and use the notation \eqref{eq:fibres} and \eqref{eq:homology}. Let $\lambda$ be a holomorphic $d$-form on $\mathcal Z$, with closed restrictions to smooth fibers.

If $a\in H_d(Z_\tau;\mathbb Q)$ satisfies $ja=0$, then its period germ $I_a$ extends to a single-valued entire function of $t$.
